"""Device helpers of the GLM-5.3 kernels: buffer access, conversions, IEEE-rounded arithmetic and
reductions."""

import inspect
import os
import struct

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from aiter.ops.flydsl.kernels import buffer_ops as bo
from aiter.ops.flydsl.kernels.dpp_utils import update_dpp_i32
from flydsl._mlir.dialects import llvm
from flydsl.expr import math as fmath
from flydsl.expr import range_constexpr, rocdl
from flydsl.expr.typing import T
from flydsl.utils.env import CompileEnvManager

THREADS = 256
WAVES = THREADS // 64
LOG2E = 1.4426950408889634
INV_FP8_MAX = struct.unpack("<f", struct.pack("<f", 1.0 / 448.0))[0]  # f32, as torch's reciprocal
F32_TINY = 1.1754943508222875e-38


class compile_once:
    """``launch`` compiled at its first call, which runs it: never on placeholder pointers."""

    def __init__(self, launch):
        self.launch, self.compiled = launch, None

    def __call__(self, *args):
        if self.compiled is None:
            self.compiled = flyc.compile(self.launch, *args)
        else:
            self.compiled(*args)


def compile_only(launch):
    """Compile a compile_once's launch without running it, into FlyDSL's disk cache, from which its first
    call loads it: so that ranks whose launches wait on each other start them together."""
    names = [n for n in inspect.signature(launch.launch.func).parameters if n != "stream"]
    var = CompileEnvManager.options["compile_only"].env_var
    old = os.environ.get(var)
    os.environ[var] = "1"
    try:
        launch.launch(*([0] * len(names)), stream=torch.cuda.current_stream())
    finally:
        if old is None:
            os.environ.pop(var)
        else:
            os.environ[var] = old


def rsrc(addr, nbytes=None):
    """A buffer resource at device address ``addr``; loads past ``nbytes`` read 0."""
    return bo.create_buffer_resource_from_addr(addr, num_records_bytes=nbytes)


def warm_code(nbytes):
    """Up to ``nbytes`` of this kernel's code from here on into the XCD's L2, a word of each 64-byte line
    (sgl-amd-mono's warm_code): code that runs once a launch then fetched from there, not from HBM (the MoE's
    weights stream every layer's code out). The words: their wait where ``hold`` takes them. Loads past the
    code's end (.Lfunc_end0) read nothing."""
    pc_left = llvm.inline_asm(
        llvm.StructType.get_literal([T.i64, T.i32]),
        [],
        "s_getpc_b64 $0\n.Lwarm_code${:uid}:\ns_mov_b32 $1, .Lfunc_end0-.Lwarm_code${:uid}",
        "=s,=s",
        has_side_effects=True,
    )
    pc = fx.Int64(llvm.extractvalue(T.i64, pc_left, [0]))
    left = fx.Int32(llvm.extractvalue(T.i32, pc_left, [1]))
    r, tid = rsrc(pc, fx.min(left, fx.Int32(nbytes))), fx.Int32(fx.thread_idx.x)
    words = fx.Int32(0)
    for i in range_constexpr(nbytes // 64 // THREADS):
        words = words | fx.Int32(bo.buffer_load(r, (tid + i * THREADS) * 16, vec_width=1, dtype=T.i32))
    return words


def hold(v):
    """``v`` through an opaque move: its loads waited for here, not dropped as unused."""
    asm = llvm.inline_asm(T.i32, [fx.Int32(v).ir_value()], "v_mov_b32 $0, $1", "=v,v", has_side_effects=True)
    return fx.Int32(asm)


def ld_f32(r, i, n=1):
    v = bo.buffer_load(r, i, vec_width=n, dtype=T.f32)
    return fx.Float32(v) if n == 1 else fx.Vector(v)


def ld_i32(r, i, cm=0):
    return fx.Int32(bo.buffer_load(r, i, vec_width=1, dtype=T.i32, cache_modifier=cm))


def bf16_values(word):
    """A word of two bf16 -> their two f32."""
    return [(word << 16).bitcast(fx.Float32), (word & fx.Int32(-65536)).bitcast(fx.Float32)]


def bf16_pair(lo, hi):
    """Two f32 -> a word of their two bf16, rounded to nearest even."""
    word = lambda v: fx.Float32(v.to(fx.BFloat16)).bitcast(fx.Int32)  # noqa: E731
    return ((word(lo) >> 16) & fx.Int32(0xFFFF)) | (word(hi) & fx.Int32(-65536))


def load_bf16x8(r, elem):
    words = fx.Vector(bo.buffer_load(r, elem // 2, vec_width=4, dtype=T.i32))
    return [v for j in range(4) for v in bf16_values(words[j])]


def fp8x4(a, b, c, d):
    """Four f32 -> one word of four E4M3, RNE."""
    lo = fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, a, b, fx.Int32(0), False))
    return fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, c, d, lo, True))


def fp8x4_f32(word):
    """A word of four E4M3 -> their four f32."""
    pairs = [fx.Vector(rocdl.cvt_pk_f32_fp8(T.vec(2, T.f32), word, hi)) for hi in (False, True)]
    return [p[j] for p in pairs for j in range(2)]


def uniform(v):
    """``v`` read from the wave's first lane: a scalar, as a buffer resource's address must be."""
    return fx.Int32(rocdl.readfirstlane(T.i32, fx.Int32(v).ir_value()))


def table_entry(table, i):
    """Entry i of an address table (int64 each), wave-uniform: a buffer resource's address must be."""
    words = fx.Vector(bo.buffer_load(rsrc(table), i * 2, vec_width=2, dtype=T.i32))
    return (fx.Int64(uniform(words[1])) << 32) | fx.Int64(fx.Uint32(uniform(words[0])))


def div_rn(a, d):
    """a / d rounded as IEEE division: FlyDSL's divide is approximate, and the quantization's ratios of
    bf16 values land on E4M3 ties often enough that one ulp off flips codes."""
    r = fx.Float32(1.0) / d
    r = fmath.fma(fmath.fma(-d, r, fx.Float32(1.0)), r, r)
    q = a * r
    return fmath.fma(fmath.fma(-q, d, a), r, q)


def rsq(v):
    """1 / sqrt(v) by the hardware's v_rsq_f32."""
    return fx.Float32(rocdl.rsq(T.f32, fx.Float32(v).ir_value()))


def sigmoid(x):
    return div_rn(fx.Float32(1.0), fx.Float32(1.0) + fx.Float32(rocdl.exp2(T.f32, (-x * LOG2E).ir_value())))


def fabs(v):
    return (v.bitcast(fx.Int32) & fx.Int32(0x7FFFFFFF)).bitcast(fx.Float32)


def fmax(a, b):
    return (a > b).select(a, b)


def add(a, b):
    return a + b


def _bits32(v):
    """(v's 32 bits as Int32, the inverse) for an f32 or i32 value; None for another type."""
    if isinstance(v, fx.Float32):
        return v.bitcast(fx.Int32), lambda x: x.bitcast(fx.Float32)
    if isinstance(v, fx.Int32):
        return v, lambda x: x
    return None


def _halves(off, x):
    """v_permlane{16,32}_swap of x with itself: every lane's (x of lane & ~off, x of lane | off)."""
    swap = rocdl.permlane32_swap if off == 32 else rocdl.permlane16_swap
    pair = swap(llvm.StructType.get_literal([T.i32, T.i32]), x.ir_value(), x.ir_value(), False, False)
    return tuple(fx.Int32(llvm.extractvalue(T.i32, pair, [j])) for j in range(2))


def xshfl(v, off):
    """v of lane lane ^ off (a power of two below 64), moved in registers: DPP below 16, a permlane swap at 16
    and 32."""
    got = _bits32(v)
    if got is None:
        return v.shuffle_xor(off, 64)
    x, back = got
    if off >= 16:
        lo, hi = _halves(off, x)
        return back(((fx.thread_idx.x % 64) & off == 0).select(hi, lo))
    # DPP controls: quad perms for 1 and 2, row shifts by 4 and 8 with bank masks for 4 and 8
    if off == 8:
        y = fx.Int32(update_dpp_i32(x, x, 0x118, 0xF, 0xC, False))
        y = fx.Int32(update_dpp_i32(y, x, 0x108, 0xF, 0x3, False))
    elif off == 4:
        y = fx.Int32(update_dpp_i32(x, x, 0x114, 0xF, 0xA, False))
        y = fx.Int32(update_dpp_i32(y, x, 0x104, 0xF, 0x5, False))
    elif off == 2:
        y = fx.Int32(update_dpp_i32(x, x, 0x4E, 0xF, 0xF, False))
    else:
        y = fx.Int32(update_dpp_i32(x, x, 0xB1, 0xF, 0xF, False))
    return back(y)


def xor_reduce(v, offsets, op):
    """op(v, v of lane ^ off) for each off in turn, in registers (xshfl); at 16 and 32 op of the swap's halves,
    the lane's own value either operand: ``op`` commutative."""
    for off in offsets:
        got = _bits32(v)
        if off >= 16 and got is not None:
            lo, hi = _halves(off, got[0])
            v = op(got[1](lo), got[1](hi))
        else:
            v = op(v, xshfl(v, off))
    return v


def xor_reduce_all(vs, offsets, op):
    """xor_reduce of each of ``vs``, the values' steps interleaved (an offset's for all of them, then the next
    offset's): the same sums, the steps' latencies overlapped instead of one value's chain after another's."""
    vs = list(vs)
    for off in offsets:
        nxt = []
        for v in vs:
            got = _bits32(v)
            if off >= 16 and got is not None:
                lo, hi = _halves(off, got[0])
                nxt.append(op(got[1](lo), got[1](hi)))
            else:
                nxt.append(op(v, xshfl(v, off)))
        vs = nxt
    return vs


def spread_reduce(vs, op):
    """xor_reduce's sums of len(vs) values (a power of two up to 64), value i's in the lanes whose top log2 n bits
    spell i (lane >> (6 - log2 n)): at 32 a lane keeps half its values and takes its partner's of them, at 16 a
    quarter, .., then the one value's xor halving on: n - 1 + 6 - log2 n moves instead of 6 n. The same pairs at
    each offset as xor_reduce, so the same sums (``op`` commutative)."""
    vs, lane, off = list(vs), fx.thread_idx.x % 64, 32
    while len(vs) > 1:
        half, low = len(vs) // 2, (lane & off) == 0
        vs = [op(low.select(a, b), xshfl(low.select(b, a), off)) for a, b in zip(vs[:half], vs[half:])]
        off //= 2
    return xor_reduce(vs[0], [1 << k for k in range(off.bit_length() - 1, -1, -1)], op)


def block_reduce(v, red, tid, op):
    """``op`` over the workgroup's THREADS values, in every thread. ``red``: LDS for WAVES f32."""
    # every lane holds its wave's result and stores it: one value, no race
    fx.ptr_store(xor_reduce(v, (32, 16, 8, 4, 2, 1), op), red + tid // 64)
    fx.gpu.barrier()
    total = fx.ptr_load(red + 0)
    for w in range_constexpr(1, WAVES):
        total = op(total, fx.ptr_load(red + w))
    fx.gpu.barrier()
    return total
